// Product Lab art: the generated Lab sprites, hue-shifted so the two labs read apart on the
// yard. Runs after build-generated-pixel (which rewrites the manifest without these entries).
import fs from 'node:fs'
import sharp from 'sharp'

const root = 'assets/v5/pixel',
  manifestPath = `${root}/manifest.json`
const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'))
const lines = [
  '// Generated by scripts/art/build-product-lab.ts (hue-shifted Lab sprites).',
  "import type { SpriteImage, Tier } from './spriteImages'",
  'export const productLabSprites: Record<string, Partial<Record<Tier, SpriteImage>>> = {',
  '  productLab: {',
]
async function main() {
  for (let level = 1; level <= 5; level++) {
    const lab = manifest[`lab:${level}`]
    if (!lab) throw new Error(`lab:${level} missing; run art:v5 first`)
    const file = `productLab_L${level}.png`
    await sharp(`${root}/buildings/${lab.file}`)
      .modulate({ hue: 140, saturation: 1.1 })
      .png({ palette: true, colours: 64, dither: 0 })
      .toFile(`${root}/buildings/${file}`)
    manifest[`productLab:${level}`] = { ...lab, id: 'productLab', file }
    lines.push(
      `    ${level}: { src: require('../../../${root}/buildings/${file}'), w: ${lab.width}, h: ${lab.height}, ax: ${lab.ax}, ay: ${lab.ay}, scale: 0.5, smooth: false },`,
    )
  }
  lines.push('  },', '}')
  fs.writeFileSync('src/v4/render/productLabSprites.ts', lines.join('\n') + '\n')
  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + '\n')
  console.log('Product Lab: 5 hue-shifted Lab sprites written')
}
main().catch(e => {
  console.error(e)
  process.exitCode = 1
})
